from collections import deque,Counter

def comps(g, col):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]!=col or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=a<h and 0<=b<w and g[a][b]==col and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   out.append(comp)
 return out

